class Solution:
    def minimizedMaximum(self, n, quantities):
        lo=max(1,(sum(quantities)+n-1)//n); hi=max(quantities)
        def can(limit):
            used=0
            for q in quantities:
                used += (q + limit - 1) // limit
                if used > n: return False
            return True
        while lo < hi:
            mid=(lo+hi)//2
            if can(mid): hi=mid
            else: lo=mid+1
        return lo

